#include <stdlib.h>

#define MAX(a,b) (a) > (b) ? (a) : (b)

typedef struct ListNode {
    int ele;
    struct ListNode* next;
} ListNode;

typedef struct LinkedList {
    int size;
    ListNode* head;
    ListNode* tail;
} LinkedList;

LinkedList* new_LinkedList();
void addLast_LinkedList(LinkedList* link, int ele);
int removeFirst_LinkedList(LinkedList* link);

int getResult(int n, int arr[], int k);

int main() {
    int n;
    scanf("%d", &n);

    int m;
    scanf("%d", &m);

    int arr[n];
    for(int i=0; i<n; i++) {
        arr[i] = 1;
    }

    for(int i=0; i<m; i++) {
        int deadIdx;
        scanf("%d", &deadIdx);

        arr[deadIdx - 1] = 0;
    }

    int k;
    scanf("%d", &k);

    printf("%d\n", getResult(n, arr, k));

    return 0;
}

int getResult(int n, int arr[], int k) {
    int left = 0;
    LinkedList* occur = new_LinkedList();
    int maxLen = 0;

    for(int right = 0; right < n; right++) {

        if(arr[right] == 0) {
            addLast_LinkedList(occur, right);

            if(occur->size > k) {
                maxLen = MAX(maxLen, right - left);
                left = removeFirst_LinkedList(occur) + 1;
                continue;
            }
        }

        maxLen = MAX(maxLen, right - left + 1);
    }

    return maxLen;
}

LinkedList* new_LinkedList() {
    LinkedList* link = (LinkedList*) malloc(sizeof(LinkedList));
    link->head = NULL;
    link->tail = NULL;
    link->size = 0;

    return link;
}

void addLast_LinkedList(LinkedList* link, int ele) {
    ListNode* node = (ListNode*) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;


    if(link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

int removeFirst_LinkedList(LinkedList* link) {
    if(link->size == 0) exit(-1);

    ListNode* removed = link->head;

    if(link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    int res = removed->ele;
    free(removed);

    return res;
}

